import { useCallback, useEffect, useMemo, useState, type ReactNode } from 'react';
import { ScriptsContext } from './ScriptsContext';
import { useLanguageServiceContext } from './LanguageServiceContext';
import { loadScripts, newId, saveDraft, saveScripts, type SavedScript } from '@/lib/storage';

type Props = { children: ReactNode; initialName: string; initialScriptId: string | null };

const BLANK = '# My world\n\nelement Sand:\n\thas color with Color(#e0b25c)\n';

export default function ScriptsProvider({ children, initialName, initialScriptId }: Props) {
  const { text, setText, compile } = useLanguageServiceContext();
  const [scripts, setScripts] = useState<SavedScript[]>(loadScripts);
  const [name, setName] = useState(initialName);
  const [activeId, setActiveId] = useState<string | null>(initialScriptId);
  const [lastSavedAt, setLastSavedAt] = useState<number | null>(null);
  // What the editor held when this script was opened or saved; edits beyond it are unsaved.
  const [baseline, setBaseline] = useState({ name: initialName, source: text });

  const active = scripts.find((s) => s.id === activeId) ?? null;
  const dirty = baseline.source !== text || baseline.name !== name;

  useEffect(() => {
    const handle = setTimeout(() => saveDraft({ name, source: text, scriptId: activeId }), 300);
    return () => clearTimeout(handle);
  }, [name, text, activeId]);

  const persist = useCallback((next: SavedScript[]) => {
    const sorted = [...next].sort((a, b) => b.updatedAt - a.updatedAt);
    setScripts(sorted);
    saveScripts(sorted);
  }, []);

  const save = useCallback(() => {
    const cleanName = name.trim() || 'Untitled world';
    const now = Date.now();
    if (cleanName !== name) setName(cleanName);
    if (active) {
      persist(scripts.map((s) => (s.id === active.id ? { ...s, name: cleanName, source: text, updatedAt: now } : s)));
    } else {
      const created = { id: newId(), name: cleanName, source: text, updatedAt: now };
      persist([created, ...scripts]);
      setActiveId(created.id);
    }
    setLastSavedAt(now);
    setBaseline({ name: cleanName, source: text });
  }, [active, name, persist, scripts, text]);

  const open = useCallback(
    (nextName: string, source: string, scriptId: string | null = null) => {
      setName(nextName);
      setActiveId(scriptId);
      setText(source);
      setBaseline({ name: nextName, source });
      setLastSavedAt(null);
      compile();
    },
    [compile, setText],
  );

  const remove = useCallback(
    (id: string) => {
      persist(scripts.filter((s) => s.id !== id));
      if (id === activeId) setActiveId(null);
    },
    [activeId, persist, scripts],
  );

  const newScript = useCallback(() => open('Untitled world', BLANK), [open]);

  const value = useMemo(
    () => ({ scripts, name, setName, activeId, dirty, save, open, remove, newScript, lastSavedAt }),
    [scripts, name, activeId, dirty, save, open, remove, newScript, lastSavedAt],
  );

  return <ScriptsContext.Provider value={value}>{children}</ScriptsContext.Provider>;
}
